local _, addon = ...
addon.localeData.deDE.texts = {
    POWER_WORD_FORTITUDE = { gruppe = { "Steh aufrecht. Deine Zuversicht ist stärker als dein Zweifel.", "Mut kann man nicht verleihen. Aber man kann ihm Halt geben.", "*zeichnet ein standfestes Zeichen aus Licht vor der Brust.*", "*legt die Hand an die Schulter und lässt eine goldene Rune aufglühen.*" }, ziel = { "Steh aufrecht. Deine Zuversicht ist stärker als dein Zweifel.", "%s, möge Eure Kraft halten, wenn die Beine müde werden.", "*zeichnet ein standfestes Zeichen aus Licht vor der Brust.*", "*legt die Hand an die Schulter und lässt eine goldene Rune aufglühen.*" }, },
    POWER_WORD_SHIELD = { gruppe = { "Manchmal ist ein Augenblick Sicherheit das größte Wunder.", "Noch ein Schlag mag kommen. Dieses Licht wird ihn empfangen.", "*legt zwei Finger an das Handgelenk und spannt einen goldenen Schutzbogen auf.*", "*prüft die schimmernde Barriere mit einer ruhigen Handbewegung.*" }, ziel = { "Manchmal ist ein Augenblick Sicherheit das größte Wunder.", "%s, dieser Schutz gibt Euch den Augenblick, den Ihr braucht.", "*legt zwei Finger an das Handgelenk und spannt einen goldenen Schutzbogen auf.*", "*prüft die schimmernde Barriere mit einer ruhigen Handbewegung.*" }, },
    CONFOUNDING_FLASH = { gruppe = { "Ein Funke Verwirrung ist manchmal die klügste Antwort.", "Ein heller Moment der Verwirrung reicht, um einen Plan zu zerlegen.", "*schnippt einen flackernden Lichtpunkt aus der Hand, der die Sicht kurz verzerrt.*", "*kippt den Kopf zur Seite, um die Wirkung des plötzlichen Aufblitzens zu prüfen.*" }, },
    STARSHARDS = { gruppe = { "Die Sterne haben lange geschwiegen. Jetzt antworten sie.", "Was am Himmel fern ist, kann hier unten überraschend scharf treffen.", "*zeichnet ein Sternbild nach und zieht funkelnde Splitter daraus hervor.*", "*streckt die Hand empor, während winzige Lichter in einem Bogen niedergehen.*" }, ziel = { "Die Sterne haben lange geschwiegen. Jetzt antworten sie.", "%s, selbst die fernen Sterne haben Euch bemerkt.", "*zeichnet ein Sternbild nach und zieht funkelnde Splitter daraus hervor.*", "*streckt die Hand empor, während winzige Lichter in einem Bogen niedergehen.*" }, },
    INNER_FIRE = { gruppe = { "Eine kleine Flamme genügt, um den Winter zu verachten.", "Die Glut in mir braucht kein Holz und keinen Wind.", "*legt beide Handflächen auf die Brust, bis Wärme durch die Robe schimmert.*", "*zieht einen kleinen Flammenkreis eng um die eigene Gestalt.*" }, },
    DISPEL_MAGIC = { gruppe = { "Fremder Zauber, deine Zeit ist abgelaufen.", "Nicht jede fremde Magie verdient ein Zuhause in dieser Welt.", "*greift nach einem unsichtbaren Faden und löst ihn aus dem Zaubergeflecht.*", "*streicht mit der offenen Hand die letzten fremden Funken fort.*" }, },
    CONTINGENCY_PLAN = { gruppe = { "Ich vertraue auf das Licht, aber ich plane für das Gegenteil.", "Vorsorge ist kein Zweifel am Licht. Sie ist Fürsorge für den Ernstfall.", "*legt zwei leuchtende Zeichen übereinander, von denen eines verborgen bleibt.*", "*prüft das unauffällige Schutzsiegel an der Schulter des Gefährten.*" }, ziel = { "Ich vertraue auf das Licht, aber ich plane für das Gegenteil.", "%s, falls alles schiefgeht, soll Euch dieser Segen auffangen.", "*legt zwei leuchtende Zeichen übereinander, von denen eines verborgen bleibt.*", "*prüft das unauffällige Schutzsiegel an der Schulter des Gefährten.*" }, },
    ELUNES_GRACE = { gruppe = { "Elune, lass mich zwischen den Schlägen hindurchschreiten.", "Zwischen zwei Herzschlägen schenkt der Mond mir einen sicheren Schritt.", "*zeichnet eine Mondsichel mit der Hand und gleitet seitlich aus der Angriffsrichtung.*", "*senkt den Blick, während silbriges Licht die eigenen Konturen umspielt.*" }, },
    FEEDBACK = { gruppe = { "Wer meine Gedanken berührt, findet einen Spiegel aus Dornen.", "Wer an meinem Geist rüttelt, weckt seine eigenen Zweifel.", "*zieht einen schimmernden Schleier eng um die Schläfen.*", "*lässt winzige Lichtstacheln aufblitzen, die sich nach innen spiegeln.*" }, },
    SHACKLE_UNDEAD = { gruppe = { "Ruhig, verlorene Seele. Dein Weg endet für einen Moment hier.", "Der Tod hat Euch nicht befreit. Und für einen Moment auch nicht die Magie.", "*legt ein blasses Band aus Licht um eine unsichtbare Gestalt.*", "*hält die Handfläche starr, während das Siegel enger gezogen wird.*" }, ziel = { "Ruhig, verlorene Seele. Dein Weg endet für einen Moment hier.", "%s, bleibt stehen. Die Lebenden müssen weiterziehen.", "*legt ein blasses Band aus Licht um eine unsichtbare Gestalt.*", "*hält die Handfläche starr, während das Siegel enger gezogen wird.*" }, },
    MANA_BURN = { gruppe = { "Eure Magie knistert so laut, dass ich sie beinahe bedauere.", "Ihr habt Eure Macht offen liegen lassen. Ich nehme nur den Überschuss.", "*schließt die Finger, als erlösche eine unsichtbare Flamme.*", "*zieht einen glühenden Funken aus dem gegnerischen Zaubergeflecht.*" }, ziel = { "Eure Magie knistert so laut, dass ich sie beinahe bedauere.", "%s, Eure Magie ist heute schneller erschöpft als Euer Hochmut.", "*schließt die Finger, als erlösche eine unsichtbare Flamme.*", "*zieht einen glühenden Funken aus dem gegnerischen Zaubergeflecht.*" }, },
    DIVINE_SPIRIT = { gruppe = { "Deine Gedanken brauchen keinen Käfig. Nur einen festen Anker.", "Klarheit wächst dort, wo wir dem Lärm keinen Platz mehr lassen.", "*legt zwei Finger an die eigene Stirn und führt einen hellen Faden zum Gefährten.*", "*öffnet die Hände, als breite sich ein ruhiger Gedanke aus.*" }, ziel = { "Deine Gedanken brauchen keinen Käfig. Nur einen festen Anker.", "%s, bewahrt einen klaren Geist, auch wenn die Welt laut wird.", "*legt zwei Finger an die eigene Stirn und führt einen hellen Faden zum Gefährten.*", "*öffnet die Hände, als breite sich ein ruhiger Gedanke aus.*" }, },
    PENANCE = { gruppe = { "Ein Urteil kann Wunde und Verband zugleich sein.", "Drei Augenblicke genügen: erkennen, handeln, wieder hoffen.", "*führt die Hand in kurzen, präzisen Bögen durch einen Strahl aus Licht.*", "*hält kurz inne, während das letzte Leuchten auf der Handfläche vergeht.*" }, },
    LEVITATE = { gruppe = { "Der Boden darf mich später zurückhaben.", "Es ist erstaunlich, wie klein Sorgen wirken, wenn die Füße den Boden verlassen.", "*hebt die Fersen an, während feiner Staub unter den Stiefeln schwebt.*", "*breitet die Arme aus und steigt einen Fingerbreit über die Erde.*" }, },
    PRAYER_OF_FORTITUDE = { gruppe = { "Möge niemand von uns heute den Mut verlieren.", "Unsere Stärke wächst, wenn niemand den nächsten Schritt allein gehen muss.", "*breitet die Arme aus und lässt mehrere goldene Schutzzeichen aufleuchten.*", "*senkt den Kopf, während der Segen von einem Gefährten zum nächsten wandert.*" }, },
    PRAYER_OF_SPIRIT = { gruppe = { "Wir atmen getrennt, doch hoffen gemeinsam.", "Mögen unsere Gedanken verschieden sein und unsere Hoffnung gemeinsam.", "*verbindet mehrere schimmernde Lichtpunkte mit einer ruhigen Geste.*", "*lauscht einen Herzschlag lang, während ein leiser Segen die Gruppe erfüllt.*" }, },
    INNER_FOCUS = { gruppe = { "Alle Stimmen verstummen. Eine Absicht bleibt.", "Kein Zweifel, kein Nebengeräusch. Nur noch der nächste Atemzug.", "*schließt die Augen und legt die Hände ruhig übereinander.*", "*atmet einmal tief ein, bis das Licht um die Fingerspitzen stillsteht.*" }, },
    POWER_INFUSION = { gruppe = { "Nimm diese Kraft. Und mach etwas Gutes daraus.", "Ich reiche Euch nicht nur Kraft, sondern mein Vertrauen.", "*führt einen leuchtenden Strom von der eigenen Hand zum Verbündeten.*", "*öffnet die Finger, als gäbe ein gespanntes Band seine Energie frei.*" }, ziel = { "Nimm diese Kraft. Und mach etwas Gutes daraus.", "%s, nehmt diese Kraft und setzt sie mit Bedacht ein.", "*führt einen leuchtenden Strom von der eigenen Hand zum Verbündeten.*", "*öffnet die Finger, als gäbe ein gespanntes Band seine Energie frei.*" }, },
    LESSER_HEAL = { gruppe = { "Nicht jede Wunde braucht ein Wunder, manche nur Geduld.", "Ein wenig Licht, ein wenig Ruhe. Mehr ist jetzt nicht nötig.", "*lässt einen warmen Lichtpunkt über die kleine Verletzung wandern.*", "*legt zwei Finger an den Verband und löst die Anspannung aus der Hand.*" }, ziel = { "Nicht jede Wunde braucht ein Wunder, manche nur Geduld.", "%s, die kleine Wunde wird uns nicht aufhalten.", "*lässt einen warmen Lichtpunkt über die kleine Verletzung wandern.*", "*legt zwei Finger an den Verband und löst die Anspannung aus der Hand.*" }, },
    SMITE = { gruppe = { "Das Licht kann sanft sein. Heute hat es andere Pläne.", "Ein Urteil braucht keine Klinge, wenn das Licht selbst antwortet.", "*zieht die Hand senkrecht herab, als öffne sich ein heller Spalt im Himmel.*", "*richtet den Blick fest nach vorn, während ein Strahl aus Licht einschlägt.*" }, ziel = { "Das Licht kann sanft sein. Heute hat es andere Pläne.", "%s, dies ist keine Predigt. Das ist die Antwort.", "*zieht die Hand senkrecht herab, als öffne sich ein heller Spalt im Himmel.*", "*richtet den Blick fest nach vorn, während ein Strahl aus Licht einschlägt.*" }, },
    RENEW = { gruppe = { "Heilung ist kein Augenblick. Sie ist ein Versprechen.", "Mit jedem Atemzug findet der Körper ein Stück seiner Kraft zurück.", "*legt die Fingerspitzen über die Verletzung und lässt kleine Lichtpunkte aufsteigen.*", "*zeichnet einen langsamen Kreis über dem Verband, bis der Schein nachklingt.*" }, ziel = { "Heilung ist kein Augenblick. Sie ist ein Versprechen.", "%s, die Heilung wirkt weiter. Gebt ihr ein wenig Zeit.", "*legt die Fingerspitzen über die Verletzung und lässt kleine Lichtpunkte aufsteigen.*", "*zeichnet einen langsamen Kreis über dem Verband, bis der Schein nachklingt.*" }, },
    DESPERATE_PRAYER = { gruppe = { "Wenn Worte versagen, bleibt ein letztes Gebet.", "Wenn mir die Kraft fehlt, bleibt wenigstens mein Glaube standhaft.", "*presst die Hände aneinander und ringt um einen einzigen Lichtfunken.*", "*blickt kurz zum Himmel, ehe ein warmer Schein den eigenen Körper umfängt.*" }, },
    DIVINE_GRACE = { gruppe = { "Nicht jetzt. Dieses Leben ist noch nicht zu Ende erzählt.", "Noch ist Zeit, ein Leben dem Abgrund zu entreißen.", "*formt mit beiden Händen eine schützende Schale aus Licht.*", "*führt einen goldenen Lichtfaden behutsam zum verwundeten Gefährten.*" }, ziel = { "Nicht jetzt. Dieses Leben ist noch nicht zu Ende erzählt.", "%s, die Gnade erreicht Euch noch. Haltet durch.", "*formt mit beiden Händen eine schützende Schale aus Licht.*", "*führt einen goldenen Lichtfaden behutsam zum verwundeten Gefährten.*" }, },
    RESURRECTION = { gruppe = { "Die Geschichte ist noch nicht zu Ende. Hörst du mich?", "Das Licht erreicht selbst jene, die unsere Stimme nicht mehr hören.", "*kniet neben dem reglosen Körper und legt beide Hände behutsam darüber.*", "*hält das heilige Symbol still, bis ein erster warmer Schimmer aufsteigt.*" }, ziel = { "Die Geschichte ist noch nicht zu Ende. Hörst du mich?", "%s, kehrt zu uns zurück. Euer Platz ist noch nicht leer.", "*kniet neben dem reglosen Körper und legt beide Hände behutsam darüber.*", "*hält das heilige Symbol still, bis ein erster warmer Schimmer aufsteigt.*" }, },
    CURE_DISEASE = { gruppe = { "Was sich eingeschlichen hat, darf wieder gehen.", "Was Euch schwächt, soll sich nicht länger festsetzen.", "*legt zwei Finger an den Verband und zieht einen trüben Schimmer daraus.*", "*wischt mit einer ruhigen Geste das letzte kränkliche Leuchten fort.*" }, ziel = { "Was sich eingeschlichen hat, darf wieder gehen.", "%s, der Krankheit bleibt hier kein weiterer Augenblick.", "*legt zwei Finger an den Verband und zieht einen trüben Schimmer daraus.*", "*wischt mit einer ruhigen Geste das letzte kränkliche Leuchten fort.*" }, },
    HEAL = { gruppe = { "Atme. Der nächste Schritt gehört dir.", "Jetzt heilt nicht nur die Haut. Auch die Kraft soll zurückkehren.", "*legt beide Hände ruhig auf die verletzte Stelle und führt das Licht zusammen.*", "*wartet, bis der warme Schein gleichmäßig über den Verband zieht.*" }, ziel = { "Atme. Der nächste Schritt gehört dir.", "%s, nehmt Euch diesen Atemzug. Der nächste wird leichter.", "*legt beide Hände ruhig auf die verletzte Stelle und führt das Licht zusammen.*", "*wartet, bis der warme Schein gleichmäßig über den Verband zieht.*" }, },
    CHASTISE = { gruppe = { "Ein Wort genügt, wenn man es mit Überzeugung spricht.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Ein Wort genügt, wenn man es mit Überzeugung spricht.", "Euer nächster Gedanke wird vorsichtiger sein, %s.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    FEAR_WARD = { gruppe = { "Dein Mut ist dein eigener. Ich bewahre ihn nur.", "Die Angst darf kommen. Aber sie darf Euch nicht beherrschen.", "*zieht einen festen Kreis vor die Stirn des Gefährten.*", "*schließt die Hand um ein Lichtzeichen, das als Schutz zurückbleibt.*" }, ziel = { "Dein Mut ist dein eigener. Ich bewahre ihn nur.", "%s, hört auf Euren Mut, nicht auf das Flüstern der Furcht.", "*zieht einen festen Kreis vor die Stirn des Gefährten.*", "*schließt die Hand um ein Lichtzeichen, das als Schutz zurückbleibt.*" }, },
    FLASH_HEAL = { gruppe = { "Keine Zeit für Predigten. Bleib bei uns!", "Jetzt zählt jede Sekunde. Das Gebet muss genügen.", "*stößt die Hand rasch vor, sodass ein kurzer Lichtimpuls aufflammt.*", "*fängt den eigenen Atem wieder ein, während das Licht schon wirkt.*" }, ziel = { "Keine Zeit für Predigten. Bleib bei uns!", "%s, bleibt bei mir! Das Licht ist schon da.", "*stößt die Hand rasch vor, sodass ein kurzer Lichtimpuls aufflammt.*", "*fängt den eigenen Atem wieder ein, während das Licht schon wirkt.*" }, },
    HOLY_FIRE = { gruppe = { "Wenn Licht brennt, bleibt keine Lüge verborgen.", "Dieses Feuer kommt nicht aus der Esse. Es antwortet auf meinen Glauben.", "*schließt die Faust um einen hellen Funken und wirft ihn mit einer Öffnung der Hand fort.*", "*blickt unbewegt auf die Spur aus goldenem Feuer.*" }, ziel = { "Wenn Licht brennt, bleibt keine Lüge verborgen.", "%s, das Licht hat heute eine brennende Antwort für Euch.", "*schließt die Faust um einen hellen Funken und wirft ihn mit einer Öffnung der Hand fort.*", "*blickt unbewegt auf die Spur aus goldenem Feuer.*" }, },
    HOLY_NOVA = { gruppe = { "Lasst uns die Dunkelheit gemeinsam zurückdrängen.", "Ein einziger Lichtschlag, damit alle wieder Luft bekommen.", "*öffnet die Arme und lässt einen Ring aus hellem Licht nach außen schnellen.*", "*dreht sich im Zentrum einer goldenen Welle und senkt langsam die Hände.*" }, },
    PRAYER_OF_HEALING = { gruppe = { "Für jeden von euch ein Atemzug Hoffnung.", "Für alle, die noch stehen, und jene, die kaum noch können.", "*hebt beide Hände, während mehrere Lichtfäden zu den Gefährten wandern.*", "*senkt den Kopf und lässt ein gemeinsames Gebet wie Wärme durch die Gruppe ziehen.*" }, },
    ABOLISH_DISEASE = { gruppe = { "Diese Krankheit hat hier kein Bleiberecht.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Diese Krankheit hat hier kein Bleiberecht.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    GREATER_HEAL = { gruppe = { "Halte durch. Ich brauche einen Moment und du bekommst viele zurück.", "Diese Wunde fordert mehr als einen schnellen Segen. Ich gebe ihr meine ganze Aufmerksamkeit.", "*stützt die Arme fest ab und sammelt einen breiten Strom goldenen Lichts.*", "*hält die Hände ruhig, bis sich die helle Strömung allmählich beruhigt.*" }, ziel = { "Halte durch. Ich brauche einen Moment und du bekommst viele zurück.", "%s, gebt mir diesen Moment. Die Heilung braucht meine ganze Kraft.", "*stützt die Arme fest ab und sammelt einen breiten Strom goldenen Lichts.*", "*hält die Hände ruhig, bis sich die helle Strömung allmählich beruhigt.*" }, },
    LIGHTWELL = { gruppe = { "Ein stiller Ort, an dem Mut wieder Wurzeln schlägt.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    LIGHTWELL_RENEW = { gruppe = { "Ein Tropfen Hoffnung lässt sich weiterreichen.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Ein Tropfen Hoffnung lässt sich weiterreichen.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    PRAYER_OF_MENDING = { gruppe = { "Möge mein Segen den Nächsten finden, der ihn braucht.", "Dieser Segen bleibt nicht stehen. Er sucht, wer ihn als Nächstes braucht.", "*lässt eine kleine Lichtkugel zwischen den Gefährten weiterwandern.*", "*streckt zwei Finger aus und weist dem schimmernden Segen den nächsten Weg.*" }, ziel = { "Möge mein Segen den Nächsten finden, der ihn braucht.", "%s, nehmt den Segen an. Er wird auch andere finden.", "*lässt eine kleine Lichtkugel zwischen den Gefährten weiterwandern.*", "*streckt zwei Finger aus und weist dem schimmernden Segen den nächsten Weg.*" }, },
    SHADOW_WORD_PAIN = { gruppe = { "Ein einziges Wort. Der Rest ist eure Erinnerung daran.", "Eine Silbe genügt, um einen Gedanken mit Dornen zu umgeben.", "*senkt das Kinn, während ein dunkles Zeichen über der Handfläche entsteht.*", "*entlässt ein raues Flüstern, das keinen sichtbaren Ursprung hat.*" }, ziel = { "Ein einziges Wort. Der Rest ist eure Erinnerung daran.", "%s, dieses Wort wird Euch länger begleiten, als Ihr möchtet.", "*senkt das Kinn, während ein dunkles Zeichen über der Handfläche entsteht.*", "*entlässt ein raues Flüstern, das keinen sichtbaren Ursprung hat.*" }, },
    FADE = { gruppe = { "Man muss nicht verschwinden, um übersehen zu werden.", "Ein Schritt aus dem Blickfeld genügt. Die Schatten erledigen den Rest.", "*zieht den Schatten des Mantels wie einen Schleier über die Schultern.*", "*senkt den Blick und wird im Gewimmel beinahe unsichtbar.*" }, },
    HEX_OF_WEAKNESS = { gruppe = { "Stärke ist eine Geschichte, die man euch zu oft erzählt hat.", "Ein Fluch braucht keine Klinge, um Kraft zu nehmen.", "*verwebt drei dunkle Zeichen zu einem schmalen Band.*", "*öffnet die Hand, und eine zitternde Rune gleitet davon.*" }, ziel = { "Stärke ist eine Geschichte, die man euch zu oft erzählt hat.", "%s, Eure Stärke hat gerade einen unerwarteten Preis.", "*verwebt drei dunkle Zeichen zu einem schmalen Band.*", "*öffnet die Hand, und eine zitternde Rune gleitet davon.*" }, },
    MIND_BLAST = { gruppe = { "Manche Türen öffnet man besser nicht. Diese schon.", "Eure Gedanken sind eine Festung mit einem erstaunlich schwachen Tor.", "*presst zwei Finger an die Schläfe und stößt die Hand nach vorn.*", "*lässt eine unsichtbare Erschütterung durch die Luft laufen.*" }, ziel = { "Manche Türen öffnet man besser nicht. Diese schon.", "%s, haltet Eure Gedanken besser fest.", "*presst zwei Finger an die Schläfe und stößt die Hand nach vorn.*", "*lässt eine unsichtbare Erschütterung durch die Luft laufen.*" }, },
    TOUCH_OF_WEAKNESS = { gruppe = { "Hinter jeder Berührung wartet eine zweite Absicht.", "Diese Hand trägt keine Waffe. Das macht sie nicht harmlos.", "*betrachtet die Finger, über die ein matter Schatten wandert.*", "*schließt langsam die Faust, während eine dunkle Spur zurückbleibt.*" }, },
    PSYCHIC_SCREAM = { gruppe = { "Die Angst hat eine Stimme. Ich leihe ihr meine.", "Wenn der Verstand flieht, braucht der Körper keinen Befehl mehr.", "*reißt die Arme auseinander, als zerbreche etwas Unsichtbares zwischen ihnen.*", "*stößt einen tonlosen Schrei aus, der die Luft erzittern lässt.*" }, },
    DARK_SACRIFICE = { gruppe = { "Ein Preis muss bezahlt werden. Heute kenne ich den Namen des Schuldners.", "Macht verlangt ihren Tribut. Ich kenne die Rechnung.", "*zeichnet ein schwarzes Zeichen in die eigene Handfläche.*", "*schließt die Augen, während ein dunkles Leuchten kurz aufflackert.*" }, },
    DEVOURING_PLAGUE = { gruppe = { "Euer Hochmut hat Wurzeln. Ich ziehe daran.", "Manche Fäulnis beginnt mit einem einzigen unbedachten Atemzug.", "*zieht einen krankhaften Schleier aus dunklem Dunst zusammen.*", "*lässt die Hand sinken, während grünlicher Nebel davonkriecht.*" }, ziel = { "Euer Hochmut hat Wurzeln. Ich ziehe daran.", "%s, selbst Euer Hochmut kann diese Krankheit nicht abschütteln.", "*zieht einen krankhaften Schleier aus dunklem Dunst zusammen.*", "*lässt die Hand sinken, während grünlicher Nebel davonkriecht.*" }, },
    MIND_FLAY = { gruppe = { "Der Verstand ist ein feines Gewebe. Hörst du es reißen?", "Ein Gedanke nach dem anderen. Ich löse sie behutsam voneinander.", "*hält zwei Finger an die Schläfe und zieht einen violetten Faden durch die Luft.*", "*verengt die Augen, während ein dünner Schattenstrahl pulsiert.*" }, ziel = { "Der Verstand ist ein feines Gewebe. Hörst du es reißen?", "%s, Eure Gedanken verlieren gerade ihren Halt.", "*hält zwei Finger an die Schläfe und zieht einen violetten Faden durch die Luft.*", "*verengt die Augen, während ein dünner Schattenstrahl pulsiert.*" }, },
    MIND_SOOTHE = { gruppe = { "Schlafende Zweifel sind die besten Verbündeten.", "Ein ruhiger Geist stellt weniger Fragen. Das kommt uns gelegen.", "*senkt die Handfläche langsam, als glätte sie eine unsichtbare Welle.*", "*atmet geräuschlos aus, während die Unruhe ringsum nachlässt.*" }, ziel = { "Schlafende Zweifel sind die besten Verbündeten.", "%s, ein wenig Gelassenheit wird Euch jetzt guttun.", "*senkt die Handfläche langsam, als glätte sie eine unsichtbare Welle.*", "*atmet geräuschlos aus, während die Unruhe ringsum nachlässt.*" }, },
    SHADOWGUARD = { gruppe = { "Ich trage meine Dunkelheit mit Würde. Und mit Dornen.", "Greift nur an. Der Schatten vergisst selten, wer ihn weckt.", "*zieht dunkle Funken in einem Kreis um die eigene Gestalt.*", "*wendet die offene Hand nach außen, während ein schützender Schleier aufglimmt.*" }, },
    MIND_VISION = { gruppe = { "Deine Augen werden mir Dinge zeigen, die du übersiehst.", "Die Entfernung schützt Eure Geheimnisse nicht vor meinen Augen.", "*legt die Fingerspitzen an die Augen und blickt durch einen fremden Schatten.*", "*verharrt mit leerem Blick, während die Wahrnehmung anderswohin wandert.*" }, ziel = { "Deine Augen werden mir Dinge zeigen, die du übersiehst.", "%s, ich sehe nun einen Ausschnitt Eurer Welt.", "*legt die Fingerspitzen an die Augen und blickt durch einen fremden Schatten.*", "*verharrt mit leerem Blick, während die Wahrnehmung anderswohin wandert.*" }, },
    MIND_CONTROL = { gruppe = { "Für einen Moment wird deine Entscheidung meine sein.", "Ein einziger fremder Gedanke, und schon ändert sich der Weg.", "*zieht eine unsichtbare Schnur langsam zwischen Daumen und Zeigefinger.*", "*neigt den Kopf, während ein dunkles Zeichen über der Stirn aufscheint.*" }, ziel = { "Für einen Moment wird deine Entscheidung meine sein.", "%s, für einen Moment geht Ihr dorthin, wohin ich Euch führe.", "*zieht eine unsichtbare Schnur langsam zwischen Daumen und Zeigefinger.*", "*neigt den Kopf, während ein dunkles Zeichen über der Stirn aufscheint.*" }, },
    SHADOW_PROTECTION = { gruppe = { "Ich kenne die Nacht. Deshalb fürchte ich sie nicht.", "Die Finsternis kennt viele Wege. Dieser Schutz versperrt ihr einen.", "*legt einen stillen, violetten Schleier um den Gefährten.*", "*prüft den dunklen Schutzkreis mit einer kreisenden Handbewegung.*" }, ziel = { "Ich kenne die Nacht. Deshalb fürchte ich sie nicht.", "%s, dieser Schatten soll Euch vor den anderen bewahren.", "*legt einen stillen, violetten Schleier um den Gefährten.*", "*prüft den dunklen Schutzkreis mit einer kreisenden Handbewegung.*" }, },
    SHADOW_WORD_DEATH = { gruppe = { "Dies ist das Wort, das man nicht zurücknimmt.", "Ein letztes Wort wiegt schwerer als alle Drohungen davor.", "*formt eine schmale schwarze Rune zwischen zwei Fingern.*", "*senkt die Hand, während ein dunkler Impuls davonfährt.*" }, ziel = { "Dies ist das Wort, das man nicht zurücknimmt.", "%s, dieses Wort lasse ich nicht leichtfertig los.", "*formt eine schmale schwarze Rune zwischen zwei Fingern.*", "*senkt die Hand, während ein dunkler Impuls davonfährt.*" }, },
    PRAYER_OF_SHADOW_PROTECTION = { gruppe = { "Wir gehen durch die Finsternis, nicht in ihr verloren.", "Wir stehen zusammen, auch wenn das Licht fern scheint.", "*hebt beide Hände, während sich dunkle Schutzzeichen um die Gruppe legen.*", "*senkt den Kopf und verbindet mehrere violette Schutzringe miteinander.*" }, },
    VAMPIRIC_EMBRACE = { gruppe = { "Seltsam, wie nah Leid und Trost beieinanderliegen.", "Aus Finsternis kann manchmal Trost entstehen. Der Preis bleibt bitter.", "*zieht einen dunklen Faden aus der Luft und lässt ihn in warmes Leuchten übergehen.*", "*öffnet die Arme, während ein flüchtiger violetter Schimmer über die Gefährten streicht.*" }, ziel = { "Seltsam, wie nah Leid und Trost beieinanderliegen.", "%s, selbst diese Finsternis kann den Lebenden Kraft schenken.", "*zieht einen dunklen Faden aus der Luft und lässt ihn in warmes Leuchten übergehen.*", "*öffnet die Arme, während ein flüchtiger violetter Schimmer über die Gefährten streicht.*" }, },
    SILENCE = { gruppe = { "Es gibt Antworten, die man nur in Stille findet.", "Kein Zauber kommt voran, wenn ihm das erste Wort fehlt.", "*legt einen Finger an die Lippen und lässt die Luft ringsum verstummen.*", "*schließt die Faust, während ein schimmernder Laut darin erlischt.*" }, ziel = { "Es gibt Antworten, die man nur in Stille findet.", "%s, behaltet Eure nächste Formel einen Moment für Euch.", "*legt einen Finger an die Lippen und lässt die Luft ringsum verstummen.*", "*schließt die Faust, während ein schimmernder Laut darin erlischt.*" }, },
    SHADOWFORM = { gruppe = { "Nichts an mir ist erloschen. Das Licht fällt nur anders.", "Ich trage den Schatten, aber ich lasse mich nicht von ihm tragen.", "*zieht den Mantel enger, während seine Umrisse in Dunkelheit verschwimmen.*", "*hebt langsam den Kopf aus einem Schleier aus violettem Dunst.*" }, },
    -- Freiwillige, unabhängig vom Zauberbuch nutzbare Priester-RP-Szenen
    BEDSIDE_PRAYER = { gruppe = { "Nicht jede Heilung beginnt mit Magie. Manche beginnt mit Zuhören.", "Auch ein leiser Atemzug verdient unsere ganze Aufmerksamkeit.", "*stellt eine Schale Wasser neben das Lager und prüft den Puls eines Verwundeten.*", "*spricht ein kurzes Gebet, ohne die Hand von der Schulter zu nehmen.*" }, ziel = { "%s, ich bleibe hier, solange Ihr mich braucht." }, },
    SHRINE_VIGIL = { gruppe = { "Der Schrein kennt heute mehr Fragen als Antworten.", "Vielleicht ist Hoffnung nur der Mut, morgen wiederzukommen.", "*entzündet eine kleine Kerze und schützt die Flamme vor dem Wind.*", "*kniet nieder und verharrt einen Augenblick in Stille.*" }, },
    CONFESSION = { gruppe = { "Ich höre zu. Ein Urteil fällt hier niemand leichtfertig.", "Man kann die Wahrheit nicht immer ändern, aber den nächsten Schritt.", "*setzt sich ruhig und legt den Stab beiseite.*", "*nickt langsam und lässt dem Gegenüber Zeit zum Sprechen.*" }, ziel = { "%s, erzählt mir, was Euch auf dem Herzen liegt." }, },
    LAST_RITES = { gruppe = { "Ein Name bleibt, auch wenn die Stimme schweigt.", "Möge der Weg jenseits unserer Sicht nicht ohne Frieden sein.", "*zieht eine Decke behutsam über die gefallene Gestalt.*", "*senkt den Kopf und spricht einen Segen für die Zurückgebliebenen.*" }, ziel = { "%s, Euer Name wird nicht vergessen." }, },
    MEDITATION = { gruppe = { "Die Stille ist kein leeres Gefäß.", "Ein guter Gedanke braucht Platz zwischen zwei Atemzügen.", "*setzt sich aufrecht hin und legt beide Hände auf die Knie.*", "*schließt die Augen und zählt langsam die Atemzüge.*" }, },
